#!/bin/bash
# Generated By: Claude Code (rits/deepseek-ai/DeepSeek-V4.1-Flash-1017)
#
# One rule under test: --recreate must not lose OpenCode conversation history.
# V2 keeps sessions in SQLite databases under the XDG data directory, so the
# filter has to carry every `*.db` WITH its write-ahead log and leave the rest
# of the directory — logs, repos, artifacts, and the credential — behind.
#
# Drives opencode_state_filter() against a fake downloaded tree. The download
# itself needs a live sandbox; the filtering does not.
#
# Run: tests/test-opencode-state.sh

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"
SANDBOX_SH="${REPO_ROOT}/scripts/sandbox.sh"

TMP="$(mktemp -d)"
# shellcheck disable=SC1091 # tests/isolate.sh: fail-closed fakes, scratch HOME
source "$(dirname "${BASH_SOURCE[0]}")/isolate.sh"
trap 'rm -rf "$TMP"' EXIT

# Lift the filter and the data path out of sandbox.sh — sourcing the script
# would run it.
HELPERS="${TMP}/helpers.sh"
sed -n '/^OPENCODE_DATA_PATH=/p;/^opencode_state_filter()/,/^}/p' "$SANDBOX_SH" > "$HELPERS"
grep -q 'opencode_state_filter' "$HELPERS" \
    || { echo "FAIL: could not lift opencode_state_filter out of sandbox.sh" >&2; exit 1; }
# Directory downloads contain the source directory's contents directly in the
# destination. Keep this assertion next to the filter test because a nested
# destination assumption makes the real recreate path preserve nothing.
grep -q '"\$remote_path" "\${dl_tmp}/\${stage_subdir}"' "$SANDBOX_SH" \
    || { echo "FAIL: state download does not use an explicit content destination" >&2; exit 1; }
grep -q 'download_agent_state "\$sandbox_name" "\$sandbox_dir" opencode-data' "$SANDBOX_SH" \
    || { echo "FAIL: OpenCode download does not use the shared downloader" >&2; exit 1; }
# The destination constant is asserted by value, not by variable name: a wrong
# path would drain nothing and lose every session on --recreate.
grep -q '^OPENCODE_DATA_PATH=/sandbox/\.local/share/opencode$' "$SANDBOX_SH" \
    || { echo "FAIL: OPENCODE_DATA_PATH does not target OpenCode's data directory" >&2; exit 1; }
# shellcheck disable=SC1090
source "$HELPERS"

fail=0
present() {
    [[ -e "${DST}/$1" ]] || { echo "FAIL: ${1} was not preserved" >&2; fail=1; }
}
absent() {
    [[ ! -e "${DST}/$1" ]] || { echo "FAIL: ${1} should not be preserved" >&2; fail=1; }
}

# A realistic data directory as downloaded from a sandbox.
SRC="${TMP}/src"
DST="${TMP}/dst"
mkdir -p "$DST"
echo 'stale key' > "${DST}/auth.json"
mkdir -p "${SRC}/log" "${SRC}/repos" "${SRC}/artifacts" "${SRC}/snapshot" \
         "${SRC}/worktree" "${SRC}/bin"
echo 'db'  > "${SRC}/opencode.db"
echo 'wal' > "${SRC}/opencode.db-wal"
echo 'shm' > "${SRC}/opencode.db-shm"
echo 'db'  > "${SRC}/opencode-next.db"
echo 'wal' > "${SRC}/opencode-next.db-wal"
echo 'KEY' > "${SRC}/auth.json"
echo 'log' > "${SRC}/log/opencode.log"
echo 'repo' > "${SRC}/repos/repo.json"
echo 'out' > "${SRC}/artifacts/artifact.txt"
echo 'snap' > "${SRC}/snapshot/snap"
echo 'wt' > "${SRC}/worktree/wt"
echo 'bin' > "${SRC}/bin/helper"

opencode_state_filter "$SRC" "$DST" || { echo "FAIL: filter reported nothing kept" >&2; fail=1; }

# The database name is not stable across releases, so every *.db travels.
for db in opencode opencode-next; do
    present "${db}.db"
    present "${db}.db-wal"
    # SQLite rebuilds -shm from the -wal and says not to move it between
    # machines; a stale one is worse than none.
    absent "${db}.db-shm"
done

# auth.json is the V1 legacy credential file, not the path V2 uses — it keeps
# `opencode auth login` credentials in the database. Preserving the old file
# would resurrect a credential the host no longer uses. See gotcha 25.
absent "auth.json"

# Per-container working data.
absent "log"
absent "repos"
absent "artifacts"
absent "snapshot"
absent "worktree"
absent "bin"

# Nothing to keep must not look like success — an empty directory would
# otherwise stage an empty upload over the real one.
EMPTY_SRC="${TMP}/empty-src"
mkdir -p "$EMPTY_SRC"
if opencode_state_filter "$EMPTY_SRC" "${TMP}/empty-dst"; then
    echo "FAIL: filter reported success on an empty source" >&2
    fail=1
fi

# Re-running after the database is checkpointed must replace the copy rather
# than accumulate WAL pairs for a database that no longer exists.
rm -f "${SRC}/opencode-next.db" "${SRC}/opencode-next.db-wal"
rm -f "${SRC}/opencode.db-wal"
opencode_state_filter "$SRC" "$DST" || true
absent "opencode-next.db"
absent "opencode.db-wal"
present "opencode.db"

if [[ $fail -eq 0 ]]; then
    echo "all opencode-state checks passed"
else
    exit 1
fi
